// Plain-language rules, one entry per rule key used in battle records.
// Paraphrased from the SRD 5.2.1 (CC-BY-4.0) for new players.

import { SPELLS } from './data.js';

export const GLOSSARY = {
  'd20-test': { title: 'D20 Tests', text: 'Attack rolls, ability checks and saving throws are all D20 Tests: roll a d20, add your modifiers, and compare the total to a target number (Armor Class or a Difficulty Class). Meet or beat it and you succeed.' },
  'attack-roll': { title: 'Attack Rolls', text: "To attack, roll a d20 and add your attack bonus (usually an ability modifier plus your Proficiency Bonus). If the total equals or beats the target's Armor Class, you hit and roll damage." },
  'armor-class': { title: 'Armor Class (AC)', text: 'How hard you are to hit. Armor sets a base number, some armor adds your Dexterity modifier, and a Shield adds 2.' },
  'ability-modifier': { title: 'Ability Modifiers', text: 'Each ability score gives a modifier: subtract 10 and halve, rounding down. A 17 Strength gives +3. Modifiers are what you actually add to rolls.' },
  'proficiency': { title: 'Proficiency Bonus', text: "You add your Proficiency Bonus to rolls for things you're trained in: your weapons, your saving throws, your skills. It is +2 at levels 1 to 4 and +3 at levels 5 to 8." },
  'advantage': { title: 'Advantage and Disadvantage', text: "With Advantage, roll two d20s and keep the higher. With Disadvantage, keep the lower. If you have both, they cancel out and you roll one die, no matter how many reasons there are for each." },
  'critical-hit': { title: 'Critical Hits', text: 'A natural 20 on an attack roll always hits and is a Critical Hit: roll all of the attack\'s damage dice twice as many times. A natural 1 always misses.' },
  'damage': { title: 'Damage', text: "Roll the weapon's damage dice and add the same ability modifier you used for the attack roll. Damage comes off Hit Points." },
  'initiative': { title: 'Initiative', text: 'At the start of a fight everyone rolls Initiative, a Dexterity check (d20 + DEX modifier). Turns go from highest to lowest, and the order repeats each round.' },
  'your-turn': { title: 'Your Turn', text: 'On your turn you can move up to your Speed and take one action. You may also get one Bonus Action if a feature gives you one, and you have one Reaction per round, which you can use even on other creatures\' turns.' },
  'movement': { title: 'Movement', text: 'On a grid each square is 5 feet, diagonals included. You can split your movement before and after your action. Another creature\'s space counts as Difficult Terrain (each square costs 10 feet), and you can\'t end your move there or move through an enemy that can still fight.' },
  'opportunity-attack': { title: 'Opportunity Attacks', text: "When an enemy you can see leaves your reach, you can use your Reaction to make one melee attack against it. Moving away from an enemy without taking the Disengage action gives it that chance." },
  'disengage': { title: 'Disengage', text: "Take the Disengage action and your movement doesn't provoke Opportunity Attacks for the rest of the turn." },
  'dash': { title: 'Dash', text: 'Take the Dash action and you get extra movement equal to your Speed this turn.' },
  'dodge': { title: 'Dodge', text: 'Take the Dodge action and, until the start of your next turn, attack rolls against you have Disadvantage (if you can see the attacker) and you have Advantage on Dexterity saving throws.' },
  'help': { title: 'Help', text: 'Take the Help action to distract an enemy within 5 feet of you. The next attack roll one of your allies makes against it, before the start of your next turn, has Advantage.' },
  'stabilize': { title: 'Stabilizing a Dying Ally', text: 'Use the Help action next to a creature at 0 Hit Points and make a DC 10 Wisdom (Medicine) check. On a success the creature is Stable: it stops making death saving throws, though it is still Unconscious.' },
  'stable': { title: 'Stable', text: "A Stable creature at 0 Hit Points doesn't make death saving throws. It is still Unconscious until it regains Hit Points. Taking damage makes it start dying again." },
  'unconscious': { title: 'Unconscious', text: "At 0 Hit Points a hero falls Unconscious: they drop prone and can't act or move. Attacks against them have Advantage, and any hit from within 5 feet is a Critical Hit." },
  'death-saves': { title: 'Death Saving Throws', text: 'At the start of each of your turns at 0 Hit Points, roll a d20. 10 or higher is a success, below 10 a failure. Three successes and you are Stable; three failures and you die. A 1 counts as two failures; a 20 brings you back with 1 Hit Point. Taking damage at 0 HP is a failure (two on a Critical Hit).' },
  'ranged-in-melee': { title: 'Ranged Attacks in Close Combat', text: "Making a ranged attack while an enemy that can see you is within 5 feet of you gives you Disadvantage." },
  'long-range': { title: 'Range', text: 'Ranged weapons have two ranges, like 80/320. Beyond the first number you attack with Disadvantage, and you can\'t attack beyond the second.' },
  'weapon-mastery': { title: 'Weapon Mastery', text: "Some classes learn the mastery property of certain weapons. Each weapon has one, and it gives that weapon an extra effect when you use it." },
  'mastery-vex': { title: 'Mastery: Vex', text: 'If you hit a creature with a Vex weapon, you have Advantage on your next attack roll against that creature before the end of your next turn.' },
  'mastery-sap': { title: 'Mastery: Sap', text: 'If you hit a creature with a Sap weapon, it has Disadvantage on its next attack roll before the start of your next turn.' },
  'sneak-attack': { title: 'Sneak Attack (Rogue)', text: "Once per turn, a Rogue deals extra damage (1d6 at level 1) with a Finesse or Ranged weapon if the attack has Advantage, or if an ally who isn't Incapacitated is within 5 feet of the target and the attack doesn't have Disadvantage." },
  'second-wind': { title: 'Second Wind (Fighter)', text: 'As a Bonus Action, regain Hit Points equal to 1d10 + your Fighter level. A level 1 Fighter has two uses, regains one on a Short Rest and all on a Long Rest.' },
  'savage-attacker': { title: 'Savage Attacker (feat)', text: "Once per turn when you hit with a weapon, you roll the weapon's damage dice twice and use either roll. The Soldier background gives this Origin feat." },
  'alert': { title: 'Alert (feat)', text: 'Add your Proficiency Bonus to your Initiative rolls. The Criminal background gives this Origin feat.' },
  'luck': { title: 'Luck (Halfling)', text: 'When a halfling rolls a 1 on the d20 of a D20 Test, they can reroll the die and must use the new roll.' },
  'heroic-inspiration': { title: 'Heroic Inspiration', text: 'If you have Heroic Inspiration, you can spend it to reroll any die immediately after rolling it, using the new roll. Humans gain it each Long Rest.' },
  'expertise': { title: 'Expertise', text: 'Double your Proficiency Bonus for skills you have Expertise in.' },
  'skills': { title: 'Skills', text: 'A skill check is an ability check for a specific task: Medicine uses Wisdom, Stealth uses Dexterity. Add your Proficiency Bonus if you are proficient in the skill.' },
  'nimble-escape': { title: 'Nimble Escape (goblins)', text: 'Goblins can take the Disengage or Hide action as a Bonus Action, which is why they can slip out of a fight and still shoot.' },
  'stat-block': { title: 'Stat Blocks', text: "Monsters don't build their numbers like heroes do: their stat block lists the totals. A Goblin Warrior's Scimitar is +4 to hit and deals 1d6 + 2, plus 1d4 if it attacked with Advantage." },
  'ability-checks': { title: 'Ability Checks', text: 'When you try something that might fail, the game asks for an ability check: roll a d20, add the modifier for the skill or ability, and compare it to the Difficulty Class (DC). Easy is DC 10, medium 15, hard 20.' },
  'group-check': { title: 'Group Checks', text: 'When the whole party tries something together, everyone makes the check. If at least half of you succeed, the whole group succeeds.' },
  'help-check': { title: 'Help with a Check', text: 'If you are proficient in a skill, you can Help a friend with a check using it: they roll with Advantage.' },
  'saving-throws': { title: 'Saving Throws', text: 'A saving throw is your chance to avoid something bad, like a spell or a trap. Roll a d20 and add the ability modifier (plus your Proficiency Bonus if your class is proficient in that save), and try to meet the DC.' },
  'surprise': { title: 'Surprise', text: 'If a creature is surprised when a fight starts, it rolls Initiative with Disadvantage, so it usually acts late.' },
  'hit-points': { title: 'Hit Points', text: "How much punishment you can take. At level 1 you get your class's Hit Die maximum plus your Constitution modifier. At 0 Hit Points a hero falls Unconscious." },
  'temp-hp': { title: 'Temporary Hit Points', text: 'A buffer that soaks up damage before your real Hit Points. They don\'t stack: you keep the higher amount.' },
  'speed': { title: 'Speed', text: 'How far you can move on your turn, in feet. Most heroes have 30 feet; Wood Elves and Goliaths have 35.' },
  'spellcasting': { title: 'Spellcasting', text: 'Casters know cantrips, which they can cast any time, and prepared spells, which need a spell slot. Each class casts with one ability: Intelligence for Wizards; Wisdom for Clerics, Druids and Rangers; Charisma for Bards, Paladins, Sorcerers and Warlocks. Clerics, Druids and Wizards can change all their prepared spells after a Long Rest, Paladins and Rangers one, and Bards, Sorcerers and Warlocks one each time they gain a level.' },
  'cantrips': { title: 'Cantrips', text: 'Level 0 spells. They cost no spell slot, so you can cast them every turn.' },
  'spell-slots': { title: 'Spell Slots', text: 'Leveled spells use up a spell slot. A full caster (Bard, Cleric, Druid, Sorcerer, Wizard) has two level 1 slots at level 1, three at level 2, at level 3 four level 1 slots and two level 2 slots, and at level 5 the first two level 3 slots. Paladins and Rangers are half casters: two level 1 slots at level 1, and their first level 2 slots at level 5. A Warlock\'s few Pact Magic slots are all of one level: level 3 by level 5. Slots come back after a Long Rest; a Warlock\'s Pact Magic slots come back after a Short Rest too. You can spend only one spell slot per turn. Casting a spell with a higher-level slot makes it stronger: more dice, more targets, or more rays.' },
  'spell-attack': { title: 'Spell Attack Rolls', text: "Some spells make an attack roll like a weapon: d20 + your spellcasting modifier + Proficiency Bonus, against the target's Armor Class." },
  'spell-save-dc': { title: 'Spell Save DC', text: 'Other spells make the target roll a saving throw instead. Your spell save DC is 8 + your spellcasting modifier + your Proficiency Bonus.' },
  'magic-initiate': { title: 'Magic Initiate (feat)', text: "Two cantrips and one level 1 spell from another class's list. You can cast that spell once per Long Rest without a spell slot. The Acolyte and Sage backgrounds give this Origin feat." },
  'multiattack': { title: 'Multiattack', text: 'Some monsters make more than one attack when they take the Attack action. Heroes get a similar feature, Extra Attack, at level 5.' },
  'redirect-attack': { title: 'Redirect Attack (Goblin Boss)', text: 'A Reaction: when a creature attacks the Goblin Boss, a goblin next to it swaps places with it and takes the attack instead. Reactions are not only for Opportunity Attacks.' },
  'breath-weapon': { title: 'Breath Weapon (Dragonborn)', text: 'Instead of one attack of your Attack action, exhale a 15-foot Cone or a 30-foot Line (5 feet wide), your choice each time. Everything in it makes a Dexterity save (DC 8 + CON + PB): 1d10 damage of your ancestry\'s type, half on a success. Uses equal to your Proficiency Bonus per Long Rest.' },
  'adrenaline-rush': { title: 'Adrenaline Rush (Orc)', text: 'Take the Dash action as a Bonus Action and gain Temporary Hit Points equal to your Proficiency Bonus. Uses equal to your Proficiency Bonus per Short or Long Rest.' },
  'relentless-endurance': { title: 'Relentless Endurance (Orc)', text: "When you drop to 0 Hit Points but aren't killed outright, you drop to 1 instead. Once per Long Rest." },
  'dwarven-toughness': { title: 'Dwarven Toughness', text: 'Dwarves get 1 extra Hit Point per level.' },
  'class': { title: 'Classes', text: "Your class is what you do: how you fight, which armor and weapons you use, whether you cast spells. It sets your Hit Points and your best saving throws." },
  'background': { title: 'Backgrounds', text: 'Your background is what you did before adventuring. In the 2024 rules it gives your ability score increases (+2 and +1, or +1 to three), an Origin feat and two skills.' },
  'species': { title: 'Species', text: 'Your species gives you traits, like darkvision, extra toughness or a breath weapon. In the 2024 rules it does not change your ability scores.' },
  'ability-scores': { title: 'Ability Scores', text: 'Six numbers describe what you are good at: Strength, Dexterity, Constitution, Intelligence, Wisdom and Charisma. The standard array gives you 15, 14, 13, 12, 10 and 8 to place.' },
  'combat': { title: 'Combat', text: 'A fight runs in rounds. In each round every creature takes one turn, in Initiative order. It ends when one side is defeated.' },

  // Character options (2024 rules).
  'origin-feat': { title: 'Origin Feats', text: 'Your background gives you one Origin feat. A Human also picks a second Origin feat of their choice (Versatile). The Origin feats here are Alert, Magic Initiate, Savage Attacker and Skilled.' },
  'skilled': { title: 'Skilled (feat)', text: 'You gain proficiency in any combination of three skills or tools. You can take this feat more than once.' },
  'fighting-style': { title: 'Fighting Style', text: 'A Fighter picks a Fighting Style feat at level 1, and Paladins and Rangers at level 2: Archery, Defense, Great Weapon Fighting or Two-Weapon Fighting here. A Paladin can take Blessed Warrior instead, and a Ranger Druidic Warrior.' },
  'divine-order': { title: 'Divine Order (Cleric)', text: 'At level 1 a Cleric picks a role. Protector: training with Heavy armor and Martial weapons. Thaumaturge: one extra cantrip, and you add your Wisdom modifier (at least +1) to Intelligence (Arcana or Religion) checks.' },
  'archery': { title: 'Archery (Fighting Style)', text: '+2 to attack rolls you make with Ranged weapons.' },
  'defense': { title: 'Defense (Fighting Style)', text: 'While you wear Light, Medium or Heavy armor, you gain +1 to your Armor Class.' },
  'great-weapon-fighting': { title: 'Great Weapon Fighting (Fighting Style)', text: 'When you roll damage for a melee attack with a weapon you hold in two hands (a Two-Handed or Versatile weapon), treat any 1 or 2 on a damage die as a 3.' },
  'two-weapon-fighting': { title: 'Two-Weapon Fighting (Fighting Style)', text: "When you make the Light property's extra attack, you add your ability modifier to its damage." },
  'light': { title: 'Light Weapons', text: 'When you take the Attack action and attack with a Light weapon, you can make one extra attack as a Bonus Action later that turn with a different Light weapon. You don\'t add your ability modifier to the extra attack\'s damage unless it is negative (Two-Weapon Fighting changes that).' },
  'mastery-nick': { title: 'Mastery: Nick', text: "The Light property's extra attack can be made as part of the Attack action instead of as a Bonus Action. Once per turn." },
  'mastery-graze': { title: 'Mastery: Graze', text: 'If your attack roll with a Graze weapon misses, the creature still takes damage equal to the ability modifier you used for the attack.' },
  'mastery-slow': { title: 'Mastery: Slow', text: "If you hit and deal damage with a Slow weapon, the target's Speed drops by 10 feet until the start of your next turn. It doesn't stack." },
  'mastery-topple': { title: 'Mastery: Topple', text: 'If you hit with a Topple weapon, the target makes a Constitution save (DC 8 + your attack ability modifier + Proficiency Bonus) or falls Prone.' },
  'giant-ancestry': { title: 'Giant Ancestry (Goliath)', text: "A goliath's lineage gives one power, usable a number of times equal to your Proficiency Bonus per Long Rest. Cloud's Jaunt: teleport 30 feet as a Bonus Action. Fire's Burn: +1d10 Fire damage on a hit. Frost's Chill: +1d6 Cold damage and the target's Speed drops by 10 feet. Hill's Tumble: knock a Large or smaller target Prone on a hit. Stone's Endurance: a Reaction to reduce damage by 1d12 + CON. Storm's Thunder: a Reaction to deal 1d8 Thunder damage to a creature within 60 feet that damaged you." },
  'point-buy': { title: 'Point Buy', text: 'Spend 27 points on your six ability scores. Every score starts at 8; going up to 13 costs 1 point a step, 14 costs 7 in total and 15 costs 9. No score can go above 15 before your background adds to it.' },
  'standard-array': { title: 'Standard Array', text: 'Assign 15, 14, 13, 12, 10 and 8 to your six abilities, in any order.' },
  'ability-rolls': { title: 'Rolling Ability Scores', text: 'Roll four six-sided dice and add the highest three. Do it six times and assign the totals to your abilities in any order.' },
  'species-lineage': { title: 'Lineages and Legacies', text: 'Elves, gnomes, goliaths and tieflings pick a lineage, legacy or ancestry. It gives cantrips, spells or a special power, and you pick Intelligence, Wisdom or Charisma for any spells it gives.' },
  'mage-armor-ac': { title: 'Unarmored', text: "Without armor, your AC is 10 + your Dexterity modifier. Mage Armor makes it 13 + Dexterity. Wearing armor you aren't trained with gives Disadvantage on Strength and Dexterity rolls and stops you casting spells." },
  'areas': { title: 'Areas of Effect', text: 'Some spells cover an area: a Cone spreads out from you, a Line runs straight out from you, a Cube is a box, and a Sphere or Emanation spreads in every direction. You choose where to aim it. Everyone in the area is affected, friends included, unless a wall blocks the spell from that square.' },
  'targets': { title: 'Choosing Targets', text: 'A spell says what it targets: yourself, a creature (any creature, friend or foe), several creatures, a point you can see, or an area. Your target has to be within range, and you need a clear path to it.' },

  // Phase 2: conditions, terrain and sight.
  'cover': { title: 'Cover', text: "Something between you and an attacker protects you. Half Cover (a low wall, a crate, another creature) gives +2 to AC and Dexterity saves. Three-Quarters Cover gives +5. Total Cover (a solid wall) means you can't be targeted directly at all." },
  'line-of-sight': { title: 'Line of Sight', text: "To target a creature with most attacks and spells you need a clear line to it. Here, solid walls block sight completely; low walls and other creatures don't block it, but they give Half Cover." },
  'prone': { title: 'Prone', text: "A Prone creature has Disadvantage on its attack rolls. Attacks against it have Advantage from within 5 feet and Disadvantage from farther away. Standing up costs half your Speed." },
  'restrained': { title: 'Restrained', text: "A Restrained creature's Speed is 0. Its attack rolls have Disadvantage, attack rolls against it have Advantage, and it has Disadvantage on Dexterity saving throws." },
  'grappled': { title: 'Grappled', text: "A Grappled creature's Speed is 0, and it has Disadvantage on attacks against anyone but the grappler. The grappler can drag it along. To break free, use your action for a Strength (Athletics) or Dexterity (Acrobatics) check against the escape DC." },
  'frightened': { title: 'Frightened', text: "A Frightened creature has Disadvantage on ability checks and attack rolls while it can see the source of its fear, and it can't willingly move closer to it." },
  'poisoned': { title: 'Poisoned', text: 'A Poisoned creature has Disadvantage on attack rolls and ability checks.' },
  'paralyzed': { title: 'Paralyzed', text: "A Paralyzed creature can't move, act or speak. It automatically fails Strength and Dexterity saves, attacks against it have Advantage, and any hit from within 5 feet is a Critical Hit." },
  'incapacitated': { title: 'Incapacitated', text: "An Incapacitated creature can't take actions, Bonus Actions or Reactions, and it loses Concentration." },
  'exhaustion': { title: 'Exhaustion', text: 'Exhaustion comes in levels. Each level gives -2 per level to every D20 Test and takes 5 feet per level off your Speed. A Long Rest removes one level. Six levels is death.' },
  'hide': { title: 'Hide', text: "Take the Hide action while no enemy can see you (behind a solid wall here) and make a DC 15 Dexterity (Stealth) check. On a success you are Invisible to enemies: your next attack has Advantage. You are found if you attack, cast a spell, or an enemy's Passive Perception beats your Stealth total." },
  'concentration': { title: 'Concentration', text: "Some spells last while you concentrate. You can concentrate on only one at a time, so casting another ends the first. If you take damage, make a Constitution save (DC 10 or half the damage, whichever is higher) or the spell ends. It also ends if you are Incapacitated." },
  'saving-throw': { title: 'Saving Throws', text: 'A saving throw is your chance to avoid something bad, like a spell, a poison or a trap. Roll a d20 and add the ability modifier (plus your Proficiency Bonus if your class is proficient in that save), and try to meet the DC.' },
  'resistance': { title: 'Resistance', text: 'A creature with Resistance to a damage type takes half damage of that type, rounded down.' },
  'vulnerability': { title: 'Vulnerability', text: 'A creature with Vulnerability to a damage type takes double damage of that type. Skeletons take double from Bludgeoning, so bring a mace.' },
  'immunity': { title: 'Immunity', text: "A creature immune to a damage type takes no damage of that type. Some creatures are also immune to conditions, like undead that can't be Poisoned." },
  'bloodied': { title: 'Bloodied', text: 'A creature is Bloodied when it is at half its Hit Points or fewer. Some features care about it.' },
  // Monsters.
  'pack-tactics': { title: 'Pack Tactics', text: "A wolf has Advantage on an attack if one of its allies is within 5 feet of the target and isn't Incapacitated. Don't let them surround you." },
  'undead-fortitude': { title: 'Undead Fortitude (Zombie)', text: "When damage would drop a zombie to 0 Hit Points, it makes a Constitution save against DC 5 + the damage taken. On a success it stays up with 1 Hit Point. Radiant damage and Critical Hits put it down for good." },
  'recharge': { title: 'Recharge', text: 'Some monster abilities say "Recharge 5-6". Once used, the monster rolls a d6 at the start of each of its turns and gets the ability back on a 5 or 6.' },
  'unarmed-strike': { title: 'Unarmed Strike: Shove', text: "Instead of a damaging punch, an Unarmed Strike can Shove. The target makes a Strength or Dexterity save (DC 8 + your Strength modifier + Proficiency Bonus) or is pushed 5 feet away or knocked Prone, your pick. It replaces one attack." },
  // Rests and levels.
  'short-rest': { title: 'Short Rest', text: "An hour of downtime. You can spend Hit Point Dice to heal, and some features come back: a use of Second Wind, Action Surge, a use of Channel Divinity, a use of Rage or Wild Shape, all of a Monk's Focus Points, a Warlock's Pact Magic slots, and the Wizard's Arcane Recovery." },
  'long-rest': { title: 'Long Rest', text: 'Eight hours, most of it asleep. You regain all your Hit Points, all spent Hit Point Dice and all spell slots, your features recharge, and one level of Exhaustion goes away.' },
  'hit-point-dice': { title: 'Hit Point Dice', text: 'You have one Hit Point Die per level: a d12 for Barbarians; d10 for Fighters, Paladins and Rangers; d8 for Bards, Clerics, Druids, Monks, Rogues and Warlocks; d6 for Sorcerers and Wizards. During a Short Rest, roll as many as you like and add your Constitution modifier to each: you regain that many Hit Points.' },
  'level-up': { title: 'Gaining a Level', text: "Each new level raises your Hit Point maximum by your Hit Die's fixed value (6 for a d10, 5 for a d8, 4 for a d6) plus your Constitution modifier, gives you another Hit Point Die and new class features, and casters get more spell slots." },
  'subclass': { title: 'Subclasses', text: 'At level 3 each class picks a specialty. Here: Barbarians follow the Path of the Berserker, Bards join the College of Lore, Clerics take the Life Domain, Druids the Circle of the Land, Fighters become Champions, Monks follow the Warrior of the Open Hand, Paladins swear the Oath of Devotion, Rangers become Hunters, Rogues Thieves, Sorcerers take Draconic Sorcery, Warlocks the Fiend Patron, and Wizards become Evokers. Each one adds features from then on.' },
  // Class features from levels 2 and 3.
  'action-surge': { title: 'Action Surge (Fighter)', text: 'Once per Short or Long Rest, a Fighter can take one extra action on their turn. It can\'t be the Magic action, so no second spell.' },
  'tactical-mind': { title: 'Tactical Mind (Fighter)', text: 'When you fail an ability check, you can spend a use of Second Wind to roll 1d10 and add it, which may turn the failure into a success. If it still fails, the use isn\'t spent.' },
  'improved-critical': { title: 'Improved Critical (Champion)', text: 'Your weapon attacks score a Critical Hit on a 19 or a 20.' },
  'remarkable-athlete': { title: 'Remarkable Athlete (Champion)', text: 'Advantage on Initiative rolls and Strength (Athletics) checks. After you score a Critical Hit you can move up to half your Speed without provoking Opportunity Attacks.' },
  'cunning-action': { title: 'Cunning Action (Rogue)', text: 'A Rogue can take the Dash, Disengage or Hide action as a Bonus Action, so they can stab and get away in the same turn.' },
  'steady-aim': { title: 'Steady Aim (Rogue)', text: "As a Bonus Action, if you haven't moved this turn, you give yourself Advantage on your next attack roll this turn. Your Speed is 0 until the end of the turn. Advantage also turns on Sneak Attack." },
  'fast-hands': { title: 'Fast Hands (Thief)', text: 'A Thief can make a Sleight of Hand check or use an object (pick a lock, pull a lever) as a Bonus Action.' },
  'second-story-work': { title: 'Second-Story Work (Thief)', text: 'A Thief climbs at full Speed, and can jump farther using Dexterity.' },
  'channel-divinity': { title: 'Channel Divinity (Cleric)', text: 'A Cleric of level 2 or higher has two uses of Channel Divinity, getting one back on a Short Rest and all on a Long Rest. Divine Spark heals an ally or harms an enemy (1d8 + Wisdom modifier). Turn Undead drives the dead off.' },
  'turn-undead': { title: 'Turn Undead (Cleric)', text: "As a Magic action, a Cleric presents a holy symbol. Each Undead of the Cleric's choice within 30 feet makes a Wisdom save. On a failure it is Frightened and Incapacitated for a minute and tries to get away. Any damage ends it." },
  'divine-spark': { title: 'Divine Spark (Cleric)', text: 'Channel Divinity, as a Magic action: point at a creature within 30 feet. Heal it 1d8 + your Wisdom modifier, or make it save (Constitution) against your spell save DC and take that much Radiant or Necrotic damage, half on a success.' },
  'disciple-of-life': { title: 'Disciple of Life (Life Domain)', text: "When a spell cast with a spell slot restores Hit Points, the creature regains 2 + the slot's level extra." },
  'preserve-life': { title: 'Preserve Life (Life Domain)', text: 'Channel Divinity, as a Magic action: share out up to five times your Cleric level in Hit Points among Bloodied creatures within 30 feet. Nobody can be healed above half their Hit Point maximum this way.' },
  'arcane-recovery': { title: 'Arcane Recovery (Wizard)', text: 'Once a day, when a Wizard finishes a Short Rest, they regain spent spell slots whose levels add up to half their Wizard level, rounded up. None can be level 6 or higher.' },
  'rituals': { title: 'Rituals', text: "Spells with the Ritual tag can be cast slowly, taking 10 extra minutes, without a spell slot. Wizards can do it straight from their spellbook. Nothing in this campaign needs one yet." },
  'potent-cantrip': { title: 'Potent Cantrip (Evoker)', text: "When an Evoker's damaging cantrip misses, or the target succeeds on its save, the target still takes half the damage (but none of the cantrip's other effects)." },
  // Classes added later: Barbarian to Warlock.
  'rage': { title: 'Rage (Barbarian)', text: "As a Bonus Action, while not wearing Heavy armor, a Barbarian enters a Rage: Resistance to Bludgeoning, Piercing and Slashing damage, a bonus to damage with Strength attacks (+2 at levels 1 to 8), and Advantage on Strength checks and saving throws. You can't cast spells or concentrate while raging. It lasts until the end of your next turn and keeps going each turn you make an attack roll against an enemy, force an enemy to make a saving throw, or spend a Bonus Action on it, up to 10 minutes. Two uses at levels 1 and 2, three at levels 3 to 5; one comes back on a Short Rest, all on a Long Rest." },
  'unarmored-defense': { title: 'Unarmored Defense', text: 'Without armor, a Barbarian\'s Armor Class is 10 + Dexterity modifier + Constitution modifier, and a Shield still counts. A Monk\'s is 10 + Dexterity modifier + Wisdom modifier, with no armor and no Shield.' },
  'danger-sense': { title: 'Danger Sense (Barbarian)', text: "From level 2, a Barbarian has Advantage on Dexterity saving throws unless Incapacitated." },
  'reckless-attack': { title: 'Reckless Attack (Barbarian)', text: 'From level 2, when you make your first attack roll on your turn, you can decide to attack recklessly: you have Advantage on attack rolls using Strength until the start of your next turn, but attack rolls against you have Advantage too.' },
  'frenzy': { title: 'Frenzy (Berserker)', text: 'If you use Reckless Attack while your Rage is active, the first target you hit on your turn with a Strength-based attack takes extra damage: one d6 for each point of your Rage damage bonus (2d6 at level 3).' },
  'bardic-inspiration': { title: 'Bardic Inspiration (Bard)', text: 'As a Bonus Action, a Bard gives a creature within 60 feet a Bardic Inspiration die (a d6). Once within the next hour, when it fails a D20 Test, it can roll the die and add it, which might turn the failure into a success. You have uses equal to your Charisma modifier (at least 1), all back on a Long Rest.' },
  'cutting-words': { title: 'Cutting Words (College of Lore)', text: 'When a creature you can see within 60 feet succeeds on an attack roll or ability check, or rolls damage, you can take a Reaction and spend a Bardic Inspiration: roll the die and subtract it from the roll, which might turn a hit into a miss.' },
  'primal-order': { title: 'Primal Order (Druid)', text: 'At level 1 a Druid picks a role. Magician: one extra cantrip, and you add your Wisdom modifier (at least +1) to Intelligence (Arcana or Nature) checks. Warden: training with Martial weapons and Medium armor.' },
  'wild-shape': { title: 'Wild Shape (Druid)', text: "From level 2, a Druid can take a Bonus Action to turn into a Beast they know. You keep your own Hit Points and gain Temporary Hit Points equal to your Druid level, but use the beast's Armor Class, Speed and attacks, and you can't cast spells. It ends when you take a Bonus Action to leave it, or if you're Incapacitated or die. Two uses; one comes back on a Short Rest, all on a Long Rest." },
  'lands-aid': { title: "Land's Aid (Circle of the Land)", text: "As a Magic action, spend a use of Wild Shape and pick a point within 60 feet. Each creature of your choice in a 10-foot-radius Sphere there makes a Constitution save against your spell save DC, taking 2d6 Necrotic damage on a failure or half on a success. One creature of your choice in the area regains 2d6 Hit Points. A Circle of the Land Druid also picks a land at level 3, whose spells are always prepared." },
  'martial-arts': { title: 'Martial Arts (Monk)', text: "With no armor and no Shield, a Monk's Unarmed Strikes and Monk weapons (Simple Melee weapons, and Martial Melee weapons with the Light property) can use Dexterity instead of Strength and deal at least 1d6, the Martial Arts die. When you take the Attack action this way, you can make one Unarmed Strike as a Bonus Action." },
  'monks-focus': { title: "Monk's Focus", text: 'From level 2, a Monk has Focus Points equal to their Monk level, all back on a Short or Long Rest. Flurry of Blows: 1 point for two Unarmed Strikes as a Bonus Action. Patient Defense: Disengage as a Bonus Action, or 1 point to Disengage and Dodge. Step of the Wind: Dash as a Bonus Action, or 1 point to Disengage and Dash. Your Focus save DC is 8 + Wisdom modifier + Proficiency Bonus.' },
  'unarmored-movement': { title: 'Unarmored Movement (Monk)', text: 'From level 2, a Monk with no armor and no Shield has 10 extra feet of Speed.' },
  'uncanny-metabolism': { title: 'Uncanny Metabolism (Monk)', text: 'Once per Long Rest, when a Monk rolls Initiative, they regain all expended Focus Points and Hit Points equal to a roll of the Martial Arts die plus their Monk level.' },
  'deflect-attacks': { title: 'Deflect Attacks (Monk)', text: "From level 3, when an attack roll hits a Monk for Bludgeoning, Piercing or Slashing damage, they can take a Reaction to reduce the damage by 1d10 + Dexterity modifier + Monk level. If that brings it to 0, they can spend 1 Focus Point to redirect it: a creature within 5 feet (or 60 feet, for a ranged attack) makes a Dexterity save or takes two rolls of the Martial Arts die + Dexterity modifier." },
  'open-hand-technique': { title: 'Open Hand Technique (Warrior of the Open Hand)', text: "When you hit a creature with a Flurry of Blows strike, you can add one effect. Addle: it can't make Opportunity Attacks until the start of its next turn. Push: it makes a Strength save or is pushed up to 15 feet away. Topple: it makes a Dexterity save or falls Prone." },
  'lay-on-hands': { title: 'Lay on Hands (Paladin)', text: 'A Paladin has a pool of healing equal to five times their Paladin level, refilled on a Long Rest. As a Bonus Action, touch a creature and restore Hit Points from the pool, or spend 5 points to end the Poisoned condition on it.' },
  'blessed-warrior': { title: 'Blessed Warrior (Fighting Style)', text: 'A Paladin who takes this Fighting Style learns two Cleric cantrips, with Charisma as their spellcasting ability. Whenever you gain a Paladin level, you can swap one of them for another Cleric cantrip.' },
  'sacred-weapon': { title: 'Sacred Weapon (Oath of Devotion)', text: 'When you take the Attack action, you can spend a use of Channel Divinity to imbue a melee weapon you hold for 10 minutes: add your Charisma modifier (at least +1) to its attack rolls, and its hits can deal Radiant damage instead of their normal type.' },
  'druidic-warrior': { title: 'Druidic Warrior (Fighting Style)', text: 'A Ranger who takes this Fighting Style learns two Druid cantrips, with Wisdom as their spellcasting ability. Whenever you gain a Ranger level, you can swap one of them for another Druid cantrip.' },
  'colossus-slayer': { title: "Colossus Slayer (Hunter's Prey)", text: 'Once per turn, when you hit a creature with a weapon and it is missing any of its Hit Points, it takes an extra 1d8 damage.' },
  'horde-breaker': { title: "Horde Breaker (Hunter's Prey)", text: "Once on each of your turns, when you attack with a weapon, you can make another attack with the same weapon against a different creature within 5 feet of the first target, within the weapon's range, that you haven't attacked this turn." },
  'innate-sorcery': { title: 'Innate Sorcery (Sorcerer)', text: 'Twice per Long Rest, as a Bonus Action, a Sorcerer unleashes their magic for 1 minute: their Sorcerer spells get +1 to the spell save DC, and they have Advantage on the attack rolls of Sorcerer spells.' },
  'font-of-magic': { title: 'Font of Magic (Sorcerer)', text: 'From level 2, a Sorcerer has Sorcery Points equal to their Sorcerer level, all back on a Long Rest. As a Bonus Action, spend 2 points to make a level 1 spell slot (3 points for a level 2 slot, from level 3). With no action, turn a spell slot into points equal to its level. Slots made this way vanish on a Long Rest.' },
  'metamagic': { title: 'Metamagic (Sorcerer)', text: 'At level 2 a Sorcerer learns two Metamagic options. Each one bends a spell as you cast it for a cost in Sorcery Points, and you can use only one per spell unless an option says otherwise. Whenever you gain a Sorcerer level, you can swap one option for another.' },
  'draconic-resilience': { title: 'Draconic Resilience (Draconic Sorcery)', text: 'Your Hit Point maximum goes up by 3 at level 3, and by 1 more for each later Sorcerer level. While you wear no armor, your Armor Class is 10 + Dexterity modifier + Charisma modifier.' },
  'eldritch-invocations': { title: 'Eldritch Invocations (Warlock)', text: 'A Warlock knows one Eldritch Invocation at level 1 and three at level 2. Some need a minimum Warlock level, and some need the Eldritch Blast cantrip. Whenever you gain a Warlock level, you can swap one invocation for another you qualify for.' },
  'dark-ones-blessing': { title: "Dark One's Blessing (Fiend Patron)", text: 'When you reduce an enemy to 0 Hit Points, or someone else does while it is within 10 feet of you, you gain Temporary Hit Points equal to your Charisma modifier + your Warlock level (at least 1).' },
  'mastery-cleave': { title: 'Cleave (Weapon Mastery)', text: "When you hit a creature with a melee attack roll using this weapon, you can make a melee attack roll with it against a second creature within 5 feet of the first that is also within your reach. On a hit, the second creature takes the weapon's damage, but you don't add your ability modifier unless it is negative. Once per turn." },
  // Levels 4 and 5.
  'ability-score-improvement': { title: 'Ability Score Improvement (feat)', text: "At level 4 every class gains a feat (a Fighter also at 6, a Rogue at 10, and every class again at 8, 12 and 16). The usual pick is Ability Score Improvement: +2 to one ability score, or +1 to two. A score can't go above 20. You can take another feat you qualify for instead." },
  'grappler': { title: 'Grappler (feat)', text: '+1 to Strength or Dexterity, and Advantage on attack rolls against a creature you are grappling. (Its other parts, hitting and grappling with one Unarmed Strike and dragging at no extra cost, are not used here yet.) Needs level 4 and 13 Strength or Dexterity.' },
  'fast-movement': { title: 'Fast Movement (Barbarian)', text: 'From level 5, your Speed is 10 feet faster while you are not wearing Heavy armor.' },
  'tactical-shift': { title: 'Tactical Shift (Fighter)', text: 'From level 5, whenever you use Second Wind with a Bonus Action, you can also move up to half your Speed without provoking Opportunity Attacks.' },
  'uncanny-dodge': { title: 'Uncanny Dodge (Rogue)', text: 'From level 5, when an attacker you can see hits you with an attack roll, you can use your Reaction to halve the damage.' },
  'cunning-strike': { title: 'Cunning Strike (Rogue)', text: 'From level 5, when you deal Sneak Attack damage you can give up some of its dice for an effect. Poison (1d6): a Constitution save or Poisoned for 1 minute. Trip (1d6): a Large or smaller target makes a Dexterity save or falls Prone. Withdraw (1d6): you move up to half your Speed without provoking Opportunity Attacks. The save DC is 8 + your Dexterity modifier + your Proficiency Bonus.' },
  'stunning-strike': { title: 'Stunning Strike (Monk)', text: 'From level 5, once per turn when you hit with a Monk weapon or an Unarmed Strike, you can spend 1 Focus Point. The target makes a Constitution save. On a failure it is Stunned until the start of your next turn. On a success its Speed is halved and the next attack roll against it before then has Advantage.' },
  'stunned': { title: 'Stunned', text: 'A Stunned creature is Incapacitated: no actions, Bonus Actions or Reactions. It automatically fails Strength and Dexterity saving throws, and attack rolls against it have Advantage.' },
  'charmed': { title: 'Charmed', text: "A Charmed creature can't attack the one who charmed it or target it with harmful effects, and that creature has Advantage on social checks against it." },
  'sear-undead': { title: 'Sear Undead (Cleric)', text: 'From level 5, when you use Turn Undead, roll as many d8s as your Wisdom modifier (at least one). Each Undead that fails its save takes that much Radiant damage, and it is still Turned.' },
  'wild-resurgence': { title: 'Wild Resurgence (Druid)', text: 'From level 5, once on each of your turns, if you have no uses of Wild Shape left, you can spend a spell slot to get one back. Once per Long Rest you can also spend a use of Wild Shape to get a level 1 spell slot.' },
  'stench': { title: 'Stench (Ghast)', text: "A creature that starts its turn within 5 feet of a ghast makes a DC 10 Constitution save or is Poisoned until the start of its next turn. A success makes it immune to that ghast's Stench for 24 hours. Undead that can't be Poisoned don't care." },
  'extra-attack': { title: 'Extra Attack', text: "From level 5, a Barbarian, Fighter, Monk, Paladin or Ranger attacks twice, instead of once, whenever they take the Attack action on their turn. You can move between the two attacks, and each one can use a different weapon." },
  'jack-of-all-trades': { title: 'Jack of All Trades', text: "A Bard of level 2 or higher adds half their Proficiency Bonus (rounded down) to any ability check that uses a skill they aren't proficient in." },
  'font-of-inspiration': { title: 'Font of Inspiration', text: "From level 5, a Bard gets back all their uses of Bardic Inspiration when they finish a Short Rest as well as a Long Rest, and their Bardic Inspiration die becomes a d8." },
  'favored-enemy': { title: 'Favored Enemy', text: "A Ranger always has Hunter's Mark prepared and can cast it without a spell slot a few times per Long Rest: twice at levels 1 to 4, three times at level 5." },
  'sorcerous-restoration': { title: 'Sorcerous Restoration', text: "From level 5, when a Sorcerer finishes a Short Rest they get back spent Sorcery Points, up to half their Sorcerer level (rounded down). Once used, it comes back after a Long Rest." },
  'pact-magic': { title: 'Pact Magic', text: "A Warlock's spell slots are all of the same level, and that level rises as the Warlock does: level 1 slots at level 1, level 2 at level 3, level 3 at level 5. Pact Magic slots come back after a Short Rest or a Long Rest." },
  'life-drain': { title: 'Life Drain (Wight)', text: "In place of one of its attacks, a wight touches a creature within 5 feet: DC 13 Constitution save. On a failure the target takes Necrotic damage and its Hit Point maximum drops by the same amount until it finishes a Long Rest." },
  'indomitable': { title: 'Indomitable (Fighter)', text: 'From level 9, when you fail a saving throw you can reroll it with a bonus equal to your Fighter level, and you must use the new roll. Once per Long Rest (twice from level 13).' },
  'tactical-master': { title: 'Tactical Master (Fighter)', text: 'From level 9, when you attack with a weapon whose mastery property you can use, you can swap that property for Push, Sap or Slow for that attack.' },
  'evasion': { title: 'Evasion (Monk, Rogue)', text: 'From level 7, when an effect lets you make a Dexterity save for half damage, you take no damage on a success and half on a failure. You lose this while Incapacitated.' },
  'reliable-talent': { title: 'Reliable Talent (Rogue)', text: 'From level 7, whenever you make an ability check with a skill or tool you are proficient in, you can treat a d20 roll of 9 or lower as a 10.' },
  'blessed-healer': { title: 'Blessed Healer (Life Domain)', text: 'From level 6, when you cast a spell with a spell slot that restores Hit Points to a creature other than you, you regain 2 + the slot\'s level in Hit Points.' },
  'divine-strike': { title: 'Blessed Strikes: Divine Strike (Cleric)', text: 'From level 7, once on each of your turns when you hit a creature with a weapon attack, you can deal an extra 1d8 Necrotic or Radiant damage (Radiant here).' },
  'potent-spellcasting': { title: 'Potent Spellcasting (Cleric, Druid)', text: 'A level 7 choice: add your Wisdom modifier to the damage you deal with any Cleric or Druid cantrip.' },
  'divine-intervention': { title: 'Divine Intervention (Cleric)', text: 'From level 10, as a Magic action you can cast one Cleric spell of level 5 or lower that doesn\'t need a Reaction, without spending a spell slot or Material components. Once per Long Rest.' },
  'sculpt-spells': { title: 'Sculpt Spells (Evoker)', text: 'From level 6, when you cast an Evocation spell that makes other creatures you can see save, you can pick a number of them equal to 1 + the spell\'s level. They automatically succeed and take no damage where they would take half.' },
  'empowered-evocation': { title: 'Empowered Evocation (Evoker)', text: 'From level 10, when you cast a Wizard Evocation spell, one damage roll of it gets a bonus equal to your Intelligence modifier.' },
  'mindless-rage': { title: 'Mindless Rage (Berserker)', text: 'From level 6, you have Immunity to the Charmed and Frightened conditions while raging. If you are Charmed or Frightened when you enter a Rage, that condition ends.' },
  'feral-instinct': { title: 'Feral Instinct (Barbarian)', text: 'From level 7, you have Advantage on Initiative rolls.' },
  'instinctive-pounce': { title: 'Instinctive Pounce (Barbarian)', text: 'From level 7, as part of the Bonus Action you take to enter your Rage, you can move up to half your Speed.' },
  'brutal-strike': { title: 'Brutal Strike (Barbarian)', text: 'From level 9, when you use Reckless Attack you can give up Advantage on one Strength attack. If it hits, it deals an extra 1d10 damage and you add an effect, such as Forceful Blow: the target is pushed 15 feet straight away from you. Once per turn.' },
  'retaliation': { title: 'Retaliation (Berserker)', text: 'From level 10, when a creature within 5 feet of you damages you, you can take a Reaction to make one melee attack against it.' },
  'countercharm': { title: 'Countercharm (Bard)', text: 'From level 7, when you or a creature within 30 feet of you fails a save against an effect that makes it Charmed or Frightened, you can take a Reaction to let it reroll the save with Advantage.' },
  'magical-secrets': { title: 'Magical Secrets (Bard)', text: 'From level 10, when you choose Bard spells you can also choose spells from the Cleric, Druid and Wizard lists, and they count as Bard spells for you.' },
  'magical-discoveries': { title: 'Magical Discoveries (Lore Bard)', text: 'At level 6, you learn two spells of your choice from the Cleric, Druid or Wizard list. They are always prepared and count as Bard spells. When you gain a level you can swap one of them.' },
  'natural-recovery': { title: 'Natural Recovery (Circle of the Land)', text: 'From level 6, you can cast one of your Circle spells without a spell slot once per Long Rest. Here it is the highest-level Circle spell you have.' },
  'primal-strike': { title: 'Elemental Fury: Primal Strike (Druid)', text: 'A level 7 choice: once on each of your turns when you hit with a weapon attack or a Wild Shape beast\'s attack, you can deal an extra 1d8 Cold, Fire, Lightning or Thunder damage.' },
  'natures-ward': { title: 'Nature\'s Ward (Circle of the Land)', text: 'From level 10, you are immune to the Poisoned condition and have Resistance to one damage type set by your chosen land: Fire for arid, Cold for polar, Lightning for temperate, Poison for tropical.' },
  'empowered-strikes': { title: 'Empowered Strikes (Monk)', text: 'From level 6, your Unarmed Strikes can deal Force damage instead of their normal damage type.' },
  'wholeness-of-body': { title: 'Wholeness of Body (Warrior of the Open Hand)', text: 'From level 6, as a Bonus Action you roll your Martial Arts die and regain that many Hit Points plus your Wisdom modifier (at least 1). Uses equal to your Wisdom modifier (at least 1) per Long Rest.' },
  'heightened-focus': { title: 'Heightened Focus (Monk)', text: 'From level 10, Flurry of Blows makes three Unarmed Strikes instead of two, and Patient Defense and Step of the Wind get stronger.' },
  'self-restoration': { title: 'Self-Restoration (Monk)', text: 'From level 10, at the end of each of your turns you can end one of these conditions on yourself: Charmed, Frightened or Poisoned.' },
  'aura-of-protection': { title: 'Aura of Protection (Paladin)', text: 'From level 6, you and your allies within 10 feet of you add your Charisma modifier (at least +1) to saving throws. The aura is gone while you are Incapacitated.' },
  'aura-of-devotion': { title: 'Aura of Devotion (Oath of Devotion)', text: 'From level 7, you and your allies within your Aura of Protection have Immunity to the Charmed condition. A creature already Charmed when it enters the aura stops being Charmed while there.' },
  'abjure-foes': { title: 'Abjure Foes (Paladin)', text: 'From level 9, as a Magic action you spend one use of Channel Divinity and choose creatures you can see within 60 feet, up to your Charisma modifier (at least one). Each makes a Wisdom save or is Frightened of you for 1 minute or until it takes damage. While Frightened this way it can only move, take an action, or take a Bonus Action on its turn, not more than one.' },
  'aura-of-courage': { title: 'Aura of Courage (Paladin)', text: 'From level 10, you and your allies within your Aura of Protection have Immunity to the Frightened condition.' },
  'roving': { title: 'Roving (Ranger)', text: 'From level 6, your Speed goes up by 10 feet while you aren\'t wearing Heavy armor, and you gain a Climb Speed and a Swim Speed equal to your Speed.' },
  'multiattack-defense': { title: 'Defensive Tactics: Multiattack Defense (Hunter)', text: 'A level 7 choice: when a creature hits you with an attack, you get a +4 bonus to Armor Class against that creature\'s other attacks for the rest of the turn.' },
  'escape-the-horde': { title: 'Defensive Tactics: Escape the Horde (Hunter)', text: 'A level 7 choice: Opportunity Attacks against you have Disadvantage.' },
  'tireless': { title: 'Tireless (Ranger)', text: 'From level 10, as a Magic action you gain Temporary Hit Points equal to 1d8 + your Wisdom modifier (at least 1). Uses equal to your Wisdom modifier per Long Rest. Whenever you finish a Short Rest, your Exhaustion level, if any, drops by 1.' },
  'elemental-affinity': { title: 'Elemental Affinity (Draconic Sorcery)', text: 'From level 6, you have Resistance to the damage type tied to your draconic ancestry, and when you cast a spell that deals that type, you add your Charisma modifier to one damage roll of it.' },
  'sorcery-incarnate': { title: 'Sorcery Incarnate (Sorcerer)', text: 'From level 7, if you have no uses of Innate Sorcery left, you can spend 2 Sorcery Points to use it. While Innate Sorcery is active you can use up to two Metamagic options on each spell you cast.' },
  'dark-ones-own-luck': { title: 'Dark One\'s Own Luck (Fiend Patron)', text: 'From level 6, when you make an ability check or a saving throw, you can add a d10 to the roll after seeing it but before its effects. Uses equal to your Charisma modifier (at least one) per Long Rest, no more than once per roll.' },
  'fiendish-resilience': { title: 'Fiendish Resilience (Fiend Patron)', text: 'From level 10, choose one damage type other than Force whenever you finish a Short or Long Rest. You have Resistance to that type until you choose a different one.' },
  'lifedrinker': { title: 'Lifedrinker (Invocation)', text: 'Needs Pact of the Blade and Warlock level 9. Once on each of your turns when you hit with your pact weapon, you deal an extra 1d6 Necrotic, Psychic or Radiant damage, and you can spend a Hit Point Die to heal.' },
  // Monsters from level 6 on.
  'parry': { title: 'Parry (monster Reaction)', text: "Some trained fighters, like the Veteran, the Bandit Captain and the Knight, can take a Reaction when a melee attack would hit them and add 2 to their AC against it, which may turn the hit into a miss. A foe that has used its Reaction can't Parry until its next turn, so the second attacker in a round gets a fairer shot." },
  'aura-of-authority': { title: 'Aura of Authority (Hobgoblin Captain)', text: "While the Hobgoblin Captain isn't Incapacitated, it and its allies within 10 feet of it have Advantage on attack rolls and saving throws. Drop the captain first, or draw its troops away from it." },
  'regeneration': { title: 'Regeneration (Troll)', text: "A troll regains 15 Hit Points at the start of each of its turns. If it took Acid or Fire damage since its last turn, it doesn't regenerate that turn. A troll at 0 Hit Points only dies if it can't regenerate; otherwise it falls Prone and gets up again. Fire or Acid on a fallen troll finishes it." },
  'reach': { title: 'Reach', text: "Most melee attacks reach 5 feet, the next square. Some big creatures and some weapons reach 10 feet, so they can hit you from two squares away, and you leave their reach later when you back off, which matters for Opportunity Attacks." },
  'monster-spells': { title: 'Monster Spellcasting', text: "Some monsters cast spells, using a spell save DC and attack bonus from their stat block. A Mage can cast Fireball and Cone of Cold, step away with Misty Step, and cast Shield as a Reaction when a hit would land. The rules for saves, Concentration and areas are the same as yours." },
};

// Every spell gets an entry under its own id.
for (const [id, sp] of Object.entries(SPELLS)) {
  GLOSSARY[id] ||= { title: `${sp.name} (${sp.level ? `level ${sp.level} spell` : 'cantrip'})`, text: sp.text };
}

export const rule = (k) => GLOSSARY[k] || null;
